import pandas as pd
import json

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/cnt_batches.xlsx"

# Read the "Annealed" sheet
df = pd.read_excel(DATA_FILE, sheet_name="Annealed", header=0)

# Extract columns: Temperature (°C), Weight (%), Deriv. Weight (%/°C)
temp = df["Temperature (°C)"].dropna().tolist()
weight = df["Weight (%)"].dropna().tolist()
deriv_weight = df["Deriv. Weight (%/°C)"].dropna().tolist()

# Build ECharts option for black-and-white TGA plot
option = {
    "backgroundColor": "#ffffff",
    "title": {
        "text": "TGA / DTG – Annealed",
        "left": "center",
        "top": 10,
        "textStyle": {
            "fontSize": 8,
            "fontFamily": "Noto Sans CJK KR",
            "color": "#000000"
        }
    },
    "tooltip": {
        "trigger": "axis",
        "axisPointer": {"type": "cross"},
        "textStyle": {"fontSize": 8}
    },
    "legend": {
        "data": ["Weight (%)", "Deriv. Weight (%/°C)"],
        "top": 30,
        "textStyle": {"fontSize": 8, "color": "#000000"}
    },
    "grid": {
        "left": "12%",
        "right": "12%",
        "bottom": "15%",
        "containLabel": True
    },
    "xAxis": {
        "name": "Temperature (°C)",
        "nameTextStyle": {"fontSize": 8, "color": "#000000"},
        "type": "value",
        "min": 30,
        "max": 900,
        "axisLine": {"lineStyle": {"color": "#000000"}},
        "axisTick": {"lineStyle": {"color": "#000000"}},
        "axisLabel": {"fontSize": 8, "color": "#000000"},
        "splitLine": {"show": False}
    },
    "yAxis": [
        {
            "name": "Weight (%)",
            "nameTextStyle": {"fontSize": 8, "color": "#000000"},
            "type": "value",
            "position": "left",
            "axisLine": {"lineStyle": {"color": "#000000"}},
            "axisTick": {"lineStyle": {"color": "#000000"}},
            "axisLabel": {"fontSize": 8, "color": "#000000"},
            "splitLine": {"lineStyle": {"color": "#cccccc"}}
        },
        {
            "name": "Deriv. Weight (%/°C)",
            "nameTextStyle": {"fontSize": 8, "color": "#000000"},
            "type": "value",
            "position": "right",
            "axisLine": {"lineStyle": {"color": "#000000"}},
            "axisTick": {"lineStyle": {"color": "#000000"}},
            "axisLabel": {"fontSize": 8, "color": "#000000"},
            "splitLine": {"show": False}
        }
    ],
    "series": [
        {
            "name": "Weight (%)",
            "type": "line",
            "yAxisIndex": 0,
            "data": [[t, w] for t, w in zip(temp, weight)],
            "smooth": False,
            "symbol": "none",
            "lineStyle": {"width": 1.2, "color": "#000000"},
            "itemStyle": {"color": "#000000"}
        },
        {
            "name": "Deriv. Weight (%/°C)",
            "type": "line",
            "yAxisIndex": 1,
            "data": [[t, d] for t, d in zip(temp, deriv_weight)],
            "smooth": False,
            "symbol": "none",
            "lineStyle": {"width": 1.2, "color": "#666666", "type": "dashed"},
            "itemStyle": {"color": "#666666"}
        }
    ]
}

# Figure size: 3.5 x 2.6 inches at 96 px/inch => 336 x 249.6 px
fig_width_px = int(3.5 * 96)   # 336
fig_height_px = int(2.6 * 96)  # 249.6 -> round to 250

output = {
    "figures": [
        {
            "name": "tga_annealed_bw",
            "option": option,
            "width": fig_width_px,
            "height": fig_height_px,
            "dpi": 600,
            "formats": ["png"]
        }
    ]
}

print(json.dumps(output, ensure_ascii=False))
